import mujoco, numpy as np, time
base=open('model_ref.xml').read()
def mk(opt,extra=None):
    x=base.replace('  <compiler autolimits="true"/>\n','  <compiler autolimits="true"/>\n'+opt+'\n')
    if extra: x=x.replace('<config key="vmax" value="0.05"/>',extra)
    return x
OPT='<option jacobian="dense" solver="PGS" iterations="100" tolerance="1e-14"/>'
OPTC='<option jacobian="dense" solver="PGS" iterations="100" tolerance="1e-14"><flag contact="disable"/></option>'
cands={
 'ref':(''.strip(),None),
 'cur':(OPT,None),
 'cur+vmax0':(OPT,'<config key="vmax" value="0"/>'),
 'cur+novmax':(OPT,''),
 'curC+novmax':(OPTC,''),
}
models={k:mujoco.MjModel.from_xml_string(mk(*v)) for k,v in cands.items()}
def once(m,seed):
    d=mujoco.MjData(m); rng=np.random.default_rng(seed)
    d.qpos+=rng.normal(0,0.01,size=d.qpos.shape); mujoco.mj_forward(m,d)
    n=int(2.0/m.opt.timestep); t0=time.perf_counter()
    for _ in range(n): mujoco.mj_step(m,d)
    t=time.perf_counter()-t0
    st=np.zeros(mujoco.mj_stateSize(m,mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(m,d,st,mujoco.mjtState.mjSTATE_FULLPHYSICS); return t,st
times={k:[] for k in cands}; S={}
seeds=[300+i for i in range(8)]
for sd in seeds:
    for k,m in models.items():
        t,s=once(m,sd); times[k].append(t); S[(k,sd)]=s
rt=np.median(times['ref'])
for k in cands:
    print(f'{k:14s} med={np.median(times[k]):.4f} pct={np.median(times[k])/rt:.3f} diff={max(np.abs(S[(k,sd)]-S[("ref",sd)]).max() for sd in seeds):.2e}')
